task.vi:
Hai đoạn mã sau đây có tương đương nhau hay không?

Đoạn 1:
if (income <= 10000)
  tax = income * 0.1;
else if (income <= 20000)
  tax = 1000 + (income - 10000) * 0.15;

Đoạn 2:
if (income <= 10000)
  tax = income * 0.1;
else if (income > 10000 && income <= 20000)
  tax = 1000 + (income - 10000) * 0.15;

task.en:
Are the following statements equivalent?

Snippet 1:
if (income <= 10000)
  tax = income * 0.1;
else if (income <= 20000)
  tax = 1000 + (income - 10000) * 0.15;

Snippet 2:
if (income <= 10000)
  tax = income * 0.1;
else if (income > 10000 && income <= 20000)
  tax = 1000 + (income - 10000) * 0.15;

example.code:
#include <iostream>
#include <cstdlib>

int main()
{
    // Seed with fixed value 42 for deterministic standalone testing
    srand(42);

    int number1 = rand() % 10;
    int number2 = rand() % 10;

    // Ensure number1 >= number2
    if (number1 < number2) {
        int temp = number1;
        number1 = number2;
        number2 = temp;
    }

    std::cout << "What is " << number1 << " - " << number2 << "? ";

    int answer = 0;
    if (std::cin >> answer) {
        if (number1 - number2 == answer) {
            std::cout << "You are correct!" << std::endl;
        }
        else {
            std::cout << "Your answer is wrong. " << number1 << " - " << number2
                      << " should be " << (number1 - number2) << std::endl;
        }
    }

    return 0;
}
